using AdDatabase.API.DTOs;using AdDatabase.API.Extensions;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using AutoMapper;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[ApiController,Route("api/auth")]public class AuthController(IAuthService service,IMapper mapper):ControllerBase{[HttpPost("register")]public async Task<ActionResult<ApiResponse<AuthResult>>>Register(RegisterDto d,CancellationToken ct)=>Ok(ApiResponse<AuthResult>.Ok(await service.RegisterAsync(mapper.Map<RegisterRequest>(d),ct),"Registered"));[HttpPost("login")]public async Task<ActionResult<ApiResponse<AuthResult>>>Login(LoginDto d,CancellationToken ct)=>Ok(ApiResponse<AuthResult>.Ok(await service.LoginAsync(mapper.Map<LoginRequest>(d),ct)));[Authorize,HttpGet("profile")]public async Task<IActionResult>Profile(CancellationToken ct)=>Ok(ApiResponse<object>.Ok((object)(await service.GetProfileAsync(User.UserId(),ct)??throw new KeyNotFoundException("User not found"))));}
